# v0.8.0 S0: docs/03 の v0.8.x の行を v0.8.0〜v0.8.3 の 4 行に割り、v0.8.x の目安の注を末尾に足す（ほかの行は変えない）。
import sys

path = sys.argv[1]
s = open(path, encoding='utf-8').read()
lines = s.split('\n')
idx = [i for i, l in enumerate(lines) if l.startswith('| v0.8.x | 米PT キャンペーン②：残りの 4 任務とレーダー |')]
assert len(idx) == 1, idx
i = idx[0]

rows = [
    '| v0.8.0 | 米PT キャンペーン②a：ブラケット海峡の夜とレーダー（us_04） | ユーザーの要望（2026-11-15「us_04〜us_07 の 4 つも作ってくださいね」「あとレーダーも実装するっていってたよね。レーダーもストアで追加かな」。docs/02 §6.5「レーダー装備なら `radar_m` 以内の敵を円で表示」は書いたまま作っていなかった）。計画 spec-v0800（作る順は us_04 → us_06 → us_05 → us_07＝レーダーが史実で初めて効いた夜を最初に、あとは軽い順。1 任務 1 PATCH 以上）。us_04「ブラケット海峡の夜」（1943-08-01〜02・新月）を出撃可に: 分隊の先頭の艇の初期の SO レーダー（掃引ごとに射程の内の艦艇の位置だけを緑の輪で出す。種類・針路・速さは出さない・機は映さない・陸のそば 400 m は映らない・見越し点マーカーは目で見える艦だけ。敵はレーダーに気づかない）で、西から 30 kt で来る東京急行の駆逐艦 3 隻の列（ハード 4）と見回る護衛 1 隻を探し、目で見える 900 m まで寄って Mk 8（管から 4 本）を撃ち、ビラで揚陸して同じ海峡を全速で戻ってくる列をよけて、南西のファーガソン水道の輪へ帰る。1 隻撃沈で達成。夜明けの後は日本の水上機 4 機の空襲（設計の既定 L1。遊べるようにする前にユーザーに聞く）。日本のタブの解放は今の米PT の 3 任務のまま（設計の既定 L2）。共通の仕組み（レーダー・列の通過・海峡の両岸・迎撃の模擬）はここで作り、v0.8.1〜v0.8.3 が使う。迎撃の模擬の帯（spec §4.11）を満たし、ほかの 9 任務とそのハードは 1 ビットも変えない（setup の snapshot・g2 OK 37・main 2afe092 との再生と HUD の A/B を音の 3 つの状態で・tex-ab・凍結 20 本）。実在の人物とその夜の有名な艇は出さない（§11。体当たりの危険は一般の形）。史実の直し（v0.8.0 の調べ。S0 で種を直した）: 魚雷は Mk 13 でなく **Mk 8（管から撃った。発射の火が閃光を出した）**。段 S0〜S5（S0 data と検査（遊べない）／S1 純粋な規則＝`core/radar`・`ship-transit`・`strait-geometry`／S2 世界の配線（`?debug&mission=us_04` で遊べる・Title に出ない）／S3 迎撃の模擬と最初の表／S4 HUD・Briefing・Result／S5 出撃可・docs）。S0 済み（2026-11-15） | 出撃してすぐ北西に緑の輪（レーダーの輝点）が 1 つ出て、20 秒ほどで西から輪が並んで東へ進むか。輪を頼りに列の前へ回り、目で見える距離まで寄って撃てるか（輪だけではマーカーが出ないのが分かるか）／列が東へ抜けて 40 秒ほどで同じ海峡を西へ戻ってくる列が分かり、よけられるか（進路に止まっていると衝突・体当たりで沈むのが「理不尽／ちょうど／まだ易しい」のどれか）／レーダーが分かりやすく強すぎないか（`?debug&mission=us_04&noradar` で輪の無い夜も）と、復路の列が通る間の左上の FPS | 3〜4 |',
    '| v0.8.1 | 米PT キャンペーン②b：オルモック湾の決着（us_06。パロンポン沖） | us_06（1944-12-11〜12・月没後）を出撃可に: jp_04 の地図を米の側から。1944 年の標準の SO（`so_late`・自艇）で、パロンポン沖に止まった卯月と揚陸中の空知丸へ暗い岸を背に忍び寄って撃ち、気づいた艦から逃げる（新しい物: 止まった艦が気づいて動き出す規則・岸を背にした艇は見つかりにくい規則・敵の色の睦月型の絵・止まった艦への 1 本を通算の命中率に数えない）。夜明けは日本機 4 機の空襲（空は争奪→ユーザーの規則）。史実の直し（v0.8.0 の調べ。種はこの版の S0 で直す）: 卯月が沈んだのは湾の中でなく**パロンポン沖（レイテ島西岸）**、月は半月でなく**沈んでいた（dark）**、目的の「特攻艇に注意」は外す（震洋がいた記録は見つからない。PT-323 が失われたのは 12-10 の特攻**機**＝別の夜・別の場所）。僚艇（史実の 2 隻目）を付けるかはこの版の計画でユーザーに聞く（spec の Q7） | （この版の計画で決める） | 1.5〜2 |',
    '| v0.8.2 | 米PT キャンペーン②c：スリガオ海峡・最初の接触（us_05） | us_05（1944-10-24）を出撃可に: 第 1 分隊の先頭として、ボホール沖でレーダーに西村部隊の列を捉え、接触を保って報告し、照らされ撃たれながら生きて帰る（新しい物: 隊の艦ごとに違う寸法と砲・戦艦と重巡の絵・「追尾して報告」の点 `recon_and_attack`・無線の故障と中継の輪。v0.8.0 の列の通過・レーダー・迎撃の模擬を使う）。史実の直し（v0.8.0 の調べ。種はこの版の S0 で直す）: 最初の接触の相手は軽巡 1・駆逐艦 2 でなく**戦艦 2・重巡 1・駆逐艦 4 の列**（22:36 にレーダーで接触。軽巡 阿武隈への 1 本は 03:25 ごろの別の志摩部隊＝最初の接触ではない）、月は新月でなく**半月（輝面 46.7%）で 23:07 ごろ沈む**。史実の戦艦の列にするかはこの版の計画でユーザーに聞く（spec の Q6） | （この版の計画で決める） | 2〜3 |',
    '| v0.8.3 | 米PT キャンペーン②d：D-Day・生存者救助（us_07） | us_07（1944-06-06）を出撃可に: 初期の Higgins の PT で、触雷して沈む駆逐艦の周りの生存者を拾い、沖の駆逐艦へ渡す（新しい物: 生存者を拾う・乗せる・渡す、機雷原、Higgins の絵、`rescue` の点、米PT のタブの 7 任務の並べ方と `order` の年代順）。史実の直し（v0.8.0 の調べ。種はこの版の S0 で直す）: 触雷は**日の出（06:00）の後の 06:33**＝夜でなく**昼**（月 dark → day）、危険の主は S ボートでなく**沿岸砲と機雷**（S ボートはその朝は来なかった）、艇は Elco でなく**初期の Higgins**。S ボートを出すか（出すならハードだけ）はこの版の計画でユーザーに聞く（spec の Q5） | （この版の計画で決める） | 2.5〜3 |',
]
lines[i:i + 1] = rows

note = '- v0.8.x の目安（2026-11-15 の計画 spec-v0800 §2.2）: 4 版で合わせて 9〜12 セッション（v0.8.0 3〜4・v0.8.1 1.5〜2・v0.8.2 2〜3・v0.8.3 2.5〜3）。前の行の目安「4〜8」を超える。超える理由: 共通の仕組み（レーダー・列の通過・海峡の両岸・迎撃の模擬）を v0.8.0 で作ることと、4 つの夜がそれぞれ新しい物（止まった艦の規則・戦艦と重巡の列と報告・生存者と機雷原）を要ること。削る案（ユーザーに聞かずに選べる順）: us_06 の模擬を作らず v0.8.0 の迎撃の模擬を使う（−0.5）・us_07 の S ボートを出さない（−0.5）・us_05 の戦艦と重巡を「寸法と砲だけ違う駆逐艦の形の絵」で始める（−0.5）・us_06 の駆潜艇をハードだけにする（−0.3）。'
while lines and lines[-1] == '':
    lines.pop()
lines += ['', note, '']
open(path, 'w', encoding='utf-8').write('\n'.join(lines))
print('ok', i + 1)
